<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed,watch} from 'vue'
import {ArrowRight,ArrowUpRight,Wallet,ReceiptText,ShieldCheck,Plus,Copy,KeyRound,Gift,Check,Clock3,LockKeyhole,Layers3,Link2,Sparkles,Bell,Settings2,TrendingUp,ExternalLink,Download} from 'lucide-vue-next'
import {api,action,cash,date,labels,orderLabel,orderTone,renewalAttention,notify,copy,key,subscriptionRegions,type Row} from './lib'
import DataTable from './components/DataTable.vue'
import Modal from './components/Modal.vue'
import ProgressTrack from './components/ProgressTrack.vue'
import MembershipPage from './components/MembershipPage.vue'
import ProfilePage from './components/ProfilePage.vue'
import RenewalPage from './components/RenewalPage.vue'
import CheckoutResult from './components/CheckoutResult.vue'
import PaymentPanel from './components/PaymentPanel.vue'
import {parseCardLine} from './card-line'
const origin=location.origin
const props=defineProps<{route:string;user:Row;pub:Row}>();const emit=defineEmits<{refresh:[];logout:[]}>()
const loading=ref(true)
const data=ref<Row>({}),items=ref<Row[]>([]),busy=ref(false),error=ref(''),modal=ref(''),detail=ref<Row>({}),keyName=ref(''),newKey=ref(''),redeem=ref(''),topupAmount=ref(100),proof=ref(''),tab=ref('ledger')
const product=ref('pro'),country=ref(props.pub.default_country||'PH'),seats=ref(2),sessionText=ref(''),sessionInfo=ref<Row|null>(null),sessionError=ref(''),checking=ref(false),accepted=ref(false),renew=ref(false)
const cardLine=ref(''),cardTouched=ref(false)
const parsedCard=computed(()=>parseCardLine(cardLine.value,new Date(now.value)))
const subscriptionCurrency=computed(()=>subscriptionRegions.find(r=>r.code===country.value)?.currency||'USD')
const fullSubscription=computed(()=>props.route==='/subscribe')
const cardReady=computed(()=>!!parsedCard.value.card)
function clearCard(){cardLine.value='';cardTouched.value=false}
onUnmounted(clearCard)
watch(country,()=>{accepted.value=false})
const workspace=ref('My workspace'),premiumSeats=ref(1),detailRefreshError=ref('')
const selected=computed(()=>props.pub.products.find((p:Row)=>p.id===product.value)||props.pub.products[0])
const quotedFee=ref<number|null>(null),quoteInfo=ref<Row>({}),quoteError=ref(''),quoting=ref(false)
let quoteRevision=0,quoteController:AbortController|undefined
async function loadQuote(){
 const revision=++quoteRevision;quoteController?.abort();quotedFee.value=null;quoteInfo.value={};quoteError.value='';quoting.value=false
 if(!selected.value||!['/subscribe','/links'].includes(props.route))return
 const controller=new AbortController();quoteController=controller;quoting.value=true
 const timeout=setTimeout(()=>controller.abort(),15000)
 try{const result=await api('/quote?product_id='+encodeURIComponent(selected.value.id),'GET',undefined,{},controller.signal);if(revision===quoteRevision){quotedFee.value=result.fee;quoteInfo.value=result}}
 catch{if(revision===quoteRevision)quoteError.value='服务费报价暂时无法获取，请重试。'}
 finally{clearTimeout(timeout);if(revision===quoteRevision)quoting.value=false}
}
watch([selected,()=>props.user.fee_override,()=>props.user.membership?.current?.code,()=>props.user.membership?.current?.discount],loadQuote,{immediate:true})
let sessionTimer:ReturnType<typeof setTimeout>,sessionRevision=0,sessionController:AbortController|undefined
const now=ref(Date.now()),sessionExpired=computed(()=>!!sessionInfo.value&&new Date(sessionInfo.value.expires_at).getTime()<=now.value)
const sessionPlan=computed(()=>(({free:'免费方案',plus:'Plus',pro:'Pro',team:'Team 团队',business:'Business 团队',enterprise:'企业方案'} as Record<string,string>)[sessionInfo.value?.plan as string]||'账号方案未标注'))
const canSave=computed(()=>!busy.value&&!!selected.value&&!!sessionInfo.value&&!checking.value&&!sessionExpired.value&&quotedFee.value!==null&&accepted.value)
async function inspect(){
 clearTimeout(sessionTimer);const revision=++sessionRevision;sessionController?.abort();sessionInfo.value=null;sessionError.value='';checking.value=false
 if(!sessionText.value.trim())return
 const controller=new AbortController();sessionController=controller;checking.value=true
 const timeout=setTimeout(()=>controller.abort(),15000)
 try{let session=JSON.parse(sessionText.value);if(typeof session==='string')session=JSON.parse(session);const result=await api('/session/inspect','POST',{session},{},controller.signal);if(revision===sessionRevision){now.value=Date.now();sessionInfo.value=result}}
 catch(e){if(revision===sessionRevision)sessionError.value=controller.signal.aborted?'检查超时，请重新检查。':e instanceof SyntaxError?'请输入完整、有效的 Session JSON':(e as Error).message}
 finally{clearTimeout(timeout);if(revision===sessionRevision)checking.value=false}
}
watch(sessionText,()=>{sessionRevision++;sessionController?.abort();sessionInfo.value=null;sessionError.value='';checking.value=false;clearTimeout(sessionTimer);if(sessionText.value.trim())sessionTimer=setTimeout(inspect,600)})
let expiryTimer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{if(['/subscribe','/links'].includes(props.route))expiryTimer=setInterval(()=>{now.value=Date.now()},1000)})
onUnmounted(()=>{clearInterval(expiryTimer);clearTimeout(sessionTimer);sessionRevision++;quoteRevision++;sessionController?.abort();quoteController?.abort()})
const draftKey=ref(key());const inviteURL=computed(()=>`${location.origin}/?invite=${props.user.invite_code}`)
const orderColumns=[{key:'order',label:'订单 / 订阅账号'},{key:'product_name',label:'服务方案'},{key:'fee',label:'服务费报价'},{key:'status',label:'办理状态'},{key:'created_at',label:'创建时间'},{key:'action',label:'操作'}]
async function load(){loading.value=true;error.value='';try{if(props.route==='/home')data.value=await api('/overview');else if(props.route==='/orders'||props.route==='/renewal')items.value=(await api('/orders')).items;else if(props.route==='/wallet')data.value=await api('/wallet');else if(props.route==='/keys')items.value=(await api('/keys')).items;else if(props.route==='/invites')items.value=(await api('/invites')).items}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function submit(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;await action(fn);busy.value=false}
async function showOrder(r:Row){await action(async()=>{detail.value=await api('/orders/'+r.id);modal.value='order'})}
async function cancelOrder(id:string){await submit(async()=>{await api('/orders/'+id+'/cancel','POST',{});notify('申请已结束；已复制的链接不会因此在上游失效');modal.value='';await load()})}
async function createDraft(prepare=false){
 now.value=Date.now();if(!canSave.value)return
 const full=prepare&&fullSubscription.value
 if(full&&!cardReady.value)return
 await submit(async()=>{
  let v
  try{v=await api('/orders','POST',{product_id:selected.value.id,session:JSON.parse(sessionText.value),country:country.value,seats:selected.value.id.startsWith('team')?seats.value:1,accepted:accepted.value,...(prepare?{prepare:true,workspace_name:workspace.value,premium_seats:premiumSeats.value}:{}),...(full?{workflow:'subscription',keep_renewal:renew.value,card:parsedCard.value.card}:{})},{'Idempotency-Key':draftKey.value})}finally{if(full)clearCard()}
  draftKey.value=key();sessionText.value='';detail.value=await api('/orders/'+v.id);modal.value='order';emit('refresh');notify(full?'已受理，将自动办理付款及续费设置':prepare?'已提交结账准备；未付款或扣费':'已保存方案；未提交付款或扣费')
 })
}
let refreshTimer:ReturnType<typeof setInterval>;onMounted(()=>{load();refreshTimer=setInterval(()=>{if(!busy.value&&!modal.value&&!loading.value&&document.visibilityState==='visible'&&['/home','/orders','/wallet'].includes(props.route))load()},15000)});onUnmounted(()=>clearInterval(refreshTimer))
let detailTimer:ReturnType<typeof setInterval>,detailRefreshing=false;
onMounted(()=>{detailTimer=setInterval(async()=>{if(detailRefreshing||modal.value!=='order'||(!['queued','processing','review'].includes(detail.value.order?.status)&&!renewalAttention(detail.value.order))||document.visibilityState!=='visible')return;const id=detail.value.order.id;detailRefreshing=true;try{const v=await api('/orders/'+id,'GET',undefined,{},AbortSignal.timeout(10000));if(modal.value==='order'&&detail.value.order?.id===id){detail.value=v;detailRefreshError.value=''}}catch{detailRefreshError.value='进度暂时刷新失败，将自动重试。'}finally{detailRefreshing=false}},3000)});onUnmounted(()=>clearInterval(detailTimer))
</script>
<template><div class="customer-content" :aria-busy="loading"><div v-if="error" class="alert danger">{{error}}<button @click="load">重试</button></div>
<template v-if="route==='/home'"><section class="hero"><div><div class="eyebrow">YOUR SUBSCRIPTION DESK</div><h1>你好，{{user.name}}。<br/><span>把订阅，安排得明明白白。</span></h1><p>{{pub.site.tagline}}</p><a href="#/subscribe" class="btn mint">开始新的订阅<ArrowUpRight :size="19"/></a></div><div class="hero-art" aria-hidden="true"><div class="art-card art-back"><span>SUBSCRIPTION</span><Layers3 :size="38"/><div class="art-line"></div></div><div class="art-card art-front"><span>XUPAY / ORDERLY</span><Check :size="32"/><b>一切，井然有序。</b><div class="mini-progress"><i></i><i></i><i></i><i></i></div></div><span class="art-spark">✳</span></div></section>
<div v-if="data.announcements?.length" class="announcement-strip"><Bell :size="17"/><span class="eyebrow">最新消息</span><div class="marquee"><div><span v-for="a in data.announcements" :key="a.id">{{a.title}}：{{a.body}}</span></div></div></div>
<a v-if="user.membership" href="#/membership" class="membership-strip"><ShieldCheck :size="23"/><div><b>{{user.membership.current.code}} · {{user.membership.current.name}}</b><span>服务费减免 {{100-user.membership.current.discount}}% · 累计有效消费 {{cash(user.membership.spent)}} R</span></div><span>查看会员权益<ArrowRight :size="16"/></span></a><div class="stats-grid four"><article class="stat"><div class="stat-label">可用余额<Wallet :size="17"/></div><strong>{{cash(user.balance)}}<small>R</small></strong><a href="#/wallet">管理资金<ArrowRight :size="14"/></a></article><article class="stat"><div class="stat-label">冻结金额<LockKeyhole :size="17"/></div><strong>{{cash(user.frozen)}}<small>R</small></strong><span class="muted">仅已受理订单占用</span></article><article class="stat"><div class="stat-label">累计服务消费<TrendingUp :size="17"/></div><strong>{{cash(data.stats?.used)}}<small>R</small></strong><span class="muted">已完成服务的实际扣费</span></article><article class="stat"><div class="stat-label">订阅记录<ReceiptText :size="17"/></div><strong>{{data.stats?.orders||0}}<small>笔</small></strong><span class="muted">{{data.stats?.succeeded||0}} 笔已完成</span></article></div>
<div class="section-heading"><div><span class="eyebrow">EXPLORE SERVICES</span><h2>找到适合你的服务</h2></div><a href="#/subscribe">查看全部<ArrowUpRight :size="17"/></a></div><div class="service-grid"><a v-for="(p,i) in pub.products.slice(0,3)" :key="p.id" href="#/subscribe" class="service-card"><span class="service-index">0{{i+1}}</span><span class="pill">{{p.tag}}</span><h3>{{p.name}}</h3><p>{{p.description}}</p><div><span>服务费 <b>{{cash(p.fee)}} R</b></span><ArrowUpRight :size="21"/></div></a></div>
<div class="section-heading"><div><span class="eyebrow">RECENT ACTIVITY</span><h2>最近的订阅记录</h2></div><a href="#/orders">全部订单<ArrowRight :size="16"/></a></div><div class="panel"><DataTable :rows="data.recent_orders||[]" :columns="orderColumns" :searchable="false"><template #order="{row}"><b>{{row.email}}</b><small class="mono">{{row.id.slice(0,12)}}</small></template><template #fee="{row}">{{cash(row.fee)}} R</template><template #status="{row}"><span class="badge order-status" :class="orderTone(row)">{{orderLabel(row)}}</span></template><template #created_at="{row}">{{date(row.created_at)}}</template><template #action="{row}"><button class="text-btn" @click="showOrder(row)">查看进度</button></template></DataTable></div></template>
<MembershipPage v-else-if="route==='/membership'"/><template v-else-if="route==='/subscribe'||route==='/links'"><div class="page-heading"><div><span class="eyebrow">BUILD YOUR NEXT SUBSCRIPTION</span><h1>为下一步，选好服务。</h1><p>选择套餐与地区，清楚了解费用后再开始。</p></div><span class="pill amber"><Clock3 :size="14"/>{{fullSubscription?'提交一次 · 连续办理':'先生成结账 · 再确认付款'}}</span></div><div class="product-picker"><button v-for="p in pub.products" :key="p.id" :class="{selected:selected?.id===p.id}" @click="product=p.id"><span>{{p.tag}}</span><h3>{{p.name}}</h3><p>{{p.description}}</p><div><b>{{cash(p.fee)}}<small>R / 次</small></b><span class="select-ring"><Check v-if="selected?.id===p.id" :size="15"/></span></div></button></div>
<form class="checkout-grid" :class="{'subscription-form':fullSubscription}" autocomplete="off" @submit.prevent="createDraft(true)"><section class="panel form-panel"><div class="panel-heading"><h2><span class="number-box">01</span>配置订阅信息</h2><span>SUBSCRIPTION DETAILS</span></div><div class="form-grid"><label>订阅地区<select v-model="country"><option v-for="r in subscriptionRegions" :key="r.code" :value="r.code">{{r.name}} · {{r.currency}}</option></select></label><label v-if="selected?.id.startsWith('team')">团队席位<input v-model.number="seats" type="number" min="2" max="100"/></label></div><label v-if="selected?.id.startsWith('team')">团队空间名称<input v-model="workspace" maxlength="100" required/></label><label v-if="selected?.id==='team_premium'">高级席位<input v-model.number="premiumSeats" type="number" min="1" max="100" required/></label><label>账号 Session<textarea v-model="sessionText" :rows="fullSubscription?3:5" required maxlength="262144" autocomplete="off" spellcheck="false" placeholder="粘贴完整 Session JSON，自动识别订阅账号，无需手填邮箱。"></textarea><small>仅检查格式、账号一致性和到期时间；准备结账时由服务器核验授权；所需令牌加密暂存，办理结束或到期后清除。</small></label><p v-if="checking" class="muted">正在识别账号…</p><div v-if="sessionError" class="alert danger" role="alert"><span>{{sessionError}}</span><button type="button" class="text-btn" @click="inspect" :disabled="checking">重新检查</button></div><div v-if="sessionExpired" class="alert danger" role="alert">Session 已过期，请重新获取</div><div v-if="sessionInfo&&!sessionExpired" class="session-result"><ShieldCheck :size="20"/><div><b>{{sessionInfo.email}}</b><p>有效期内 · {{sessionPlan}} · 到期 {{date(sessionInfo.expires_at)}}</p><small>格式检查通过，尚未核验在线状态</small></div><button type="button" class="text-btn" @click="inspect">重新检查</button></div><div class="divider"></div><template v-if="fullSubscription"><section class="subscription-payment"><div class="payment-entry-heading"><h3>付款卡片</h3><span>整行粘贴 · 自动识别</span></div><label for="subscription-card-line">卡片信息<textarea id="subscription-card-line" name="subscription-card-line" v-model="cardLine" rows="2" maxlength="120" required autocomplete="off" autocapitalize="off" spellcheck="false" data-lpignore="true" data-1p-ignore="true" placeholder="卡号----MM/YY----CVV" aria-describedby="card-line-help" @blur="cardTouched=true"></textarea><small id="card-line-help">支持 卡号----MM/YY----CVV 或 卡号|MM|YYYY|CVV。仅使用本人或已获授权的银行卡。</small></label><p v-if="cardTouched&&parsedCard.error" class="card-line-error" role="alert">{{parsedCard.error}}</p><div v-if="parsedCard.card" class="card-line-ready" role="status"><ShieldCheck :size="16"/><span>格式已识别 · 尾号 {{parsedCard.card.number.slice(-4)}} · 有效期 {{parsedCard.card.month}}/{{parsedCard.card.year}}</span><button type="button" class="text-btn" @click="clearCard">清空</button></div><div class="renewal-choice"><label class="checkbox-label"><input type="checkbox" v-model="renew"/>保留自动续费</label><p>{{renew?'付款成功后保留自动续费。':'默认付款成功后关闭自动续费，保留已付费有效期。'}}</p></div></section></template><template v-else><h3>链接生成</h3><p>链接生成后本次任务即完成，可复制链接或在新窗口打开。</p><p class="small muted">仅提链不冻结或收取服务费。</p></template></section><aside class="order-summary"><span class="eyebrow">YOUR SELECTION</span><h2>{{selected?.name}}</h2><p>{{selected?.description}}</p><ul><li v-for="f in selected?.features" :key="f"><Check :size="16"/>{{f}}</li></ul><div class="summary-line"><span>目标账号</span><b class="summary-account">{{sessionInfo?.email||'粘贴 Session 后识别'}}</b></div><div class="summary-line"><span>标准服务费</span><b>{{cash(selected?.fee)}} R</b></div><div v-if="quoteInfo.membership" class="summary-line"><span>{{quoteInfo.membership.fee_override!=null?'账户专属单价':quoteInfo.membership.current.name}}</span><b>{{quoteInfo.membership.fee_override!=null?'优先计价':'减免 '+(100-quoteInfo.membership.current.discount)+'%'}}</b></div><div class="summary-line"><span>服务费报价</span><b>{{quotedFee==null?(quoting?'正在获取…':'—'):cash(quotedFee)+' R'}}</b></div><div v-if="quoteError" class="alert danger quote-error" role="alert">{{quoteError}}<button type="button" class="text-btn" @click="loadQuote" :disabled="quoting">重新获取报价</button></div><div class="summary-line"><span>上游订阅费用</span><b>按所选方案的实时含税金额结算</b></div><div class="summary-total"><span>{{fullSubscription?'本次服务费':'本次结账准备'}}</span><strong>{{fullSubscription?cash(quotedFee):'0.00'}}<small>R</small></strong></div><div class="callout">{{fullSubscription?'提交后冻结服务费，自动完成订阅付款和所选续费设置，可在订单中跟踪。':'仅生成结账链接，不扣款或冻结余额。订阅地区与代理出口对应。'}}</div><label class="checkbox-label"><input type="checkbox" v-model="accepted" required/>{{fullSubscription?'我授权按所选方案的实时含税金额付款，并同意续费设置及':'我已阅读并同意'}}<a class="text-btn" href="https://openai.com/zh-Hans-CN/policies/terms-of-use/" target="_blank" rel="noopener noreferrer">服务约定</a></label><button class="btn primary full" :disabled="!canSave||!pub.checkout_connected||(fullSubscription&&(!pub.payment_connected||!cardReady))">{{busy?'提交中…':fullSubscription?'开始订阅办理':'生成结账链接'}}<ArrowRight :size="17"/></button><button type="button" class="btn secondary full" :disabled="!canSave" @click="createDraft(false)">保存订阅方案</button></aside></form></template>
<template v-else-if="route==='/orders'"><div class="page-heading"><div><span class="eyebrow">EVERY ORDER, IN ONE PLACE</span><h1>订单中心</h1><p>查看横向进度与处理结果，保持每一步清晰。</p></div><a href="#/subscribe" class="btn primary"><Plus :size="17"/>创建方案</a></div><div class="panel"><DataTable :rows="items" :columns="orderColumns"><template #order="{row}"><b>{{row.email}}</b><small class="mono">{{row.id.slice(0,12)}}</small></template><template #fee="{row}">{{cash(row.fee)}} R</template><template #status="{row}"><span class="badge order-status" :class="orderTone(row)">{{orderLabel(row)}}</span></template><template #created_at="{row}">{{date(row.created_at)}}</template><template #action="{row}"><button class="text-btn" @click="showOrder(row)">查看进度</button></template></DataTable></div></template>
<template v-else-if="route==='/wallet'"><div class="page-heading"><div><span class="eyebrow">YOUR MONEY, MADE CLEAR</span><h1>资金账户</h1><p>余额、充值与每笔变动，一页看清。</p></div><button class="btn secondary" @click="load">刷新账本</button></div><div class="wallet-layout"><section class="balance-card"><span>账户可用金额</span><h2>{{cash(data.balance)}}<small>R</small></h2><div class="balance-bottom"><div><small>已冻结</small><b>{{cash(data.frozen)}} R</b></div><ShieldCheck :size="34"/></div></section><section class="panel redeem-panel"><div><span class="icon-tile"><Gift :size="21"/></span><h2>兑换入账</h2><p>输入兑换码，余额即时入账。</p></div><form @submit.prevent="submit(async()=>{const r=await api('/wallet/redeem','POST',{code:redeem});notify('已入账 '+cash(r.amount)+' R');redeem='';await load();emit('refresh')})"><input v-model="redeem" required placeholder="XP- 开头的兑换码" aria-label="兑换码"/><button class="btn primary" :disabled="busy">兑换<ArrowRight :size="16"/></button></form></section><section class="panel topup-panel"><span class="eyebrow">ADD FUNDS</span><h2>充值申请</h2><p>人工核实到账后入账。<br/>请先联系运营确认充值方式。</p><button class="btn secondary" @click="modal='topup'">提交申请<Plus :size="16"/></button></section></div><div class="section-heading"><div class="tabs"><button :class="{active:tab==='ledger'}" @click="tab='ledger'">资金流水</button><button :class="{active:tab==='topups'}" @click="tab='topups'">充值记录</button></div><span class="muted small">金额单位：R</span></div><div class="panel"><DataTable v-if="tab==='ledger'" :rows="data.ledger||[]" :columns="[{key:'kind',label:'类型'},{key:'amount',label:'变动金额'},{key:'balance_after',label:'变动后余额'},{key:'description',label:'说明'},{key:'created_at',label:'发生时间'}]"><template #kind="{row}">{{labels[row.kind]||row.kind}}</template><template #amount="{row}"><b :class="row.amount>0?'positive':'negative'">{{row.amount>0?'+':''}}{{cash(row.amount)}}</b></template><template #balance_after="{row}">{{cash(row.balance_after)}}</template><template #created_at="{row}">{{date(row.created_at)}}</template></DataTable><DataTable v-else :rows="data.topups||[]" :columns="[{key:'id',label:'申请编号'},{key:'amount',label:'申请金额'},{key:'status',label:'状态'},{key:'note',label:'审核说明'},{key:'created_at',label:'申请时间'},{key:'action',label:'操作'}]"><template #id="{row}"><span class="mono">{{row.id.slice(0,12)}}</span></template><template #amount="{row}">{{cash(row.amount)}}</template><template #status="{row}"><span class="badge order-status" :class="orderTone(row)">{{orderLabel(row)}}</span></template><template #created_at="{row}">{{date(row.created_at)}}</template><template #action="{row}"><button v-if="row.status==='pending'" class="text-btn" @click="submit(async()=>{await api('/topups/'+row.id+'/cancel','POST',{});await load();notify('已撤回')})">撤回</button></template></DataTable></div></template>
<template v-else-if="route==='/keys'"><div class="page-heading"><div><span class="eyebrow">BUILT TO CONNECT</span><h1>开发接入</h1><p>用专属密钥，将订单与余额接入你的系统。</p></div><button class="btn primary" @click="modal='key'"><Plus :size="17"/>新建访问密钥</button></div><div class="callout"><ShieldCheck :size="18"/>密钥仅创建时显示一次。它只能访问客户业务接口，无法访问运营接口。</div><div class="panel"><DataTable :rows="items" :columns="[{key:'name',label:'用途名称'},{key:'prefix',label:'密钥标识'},{key:'status',label:'状态'},{key:'last_used',label:'最近使用'},{key:'action',label:'操作'}]"><template #prefix="{row}"><code>{{row.prefix}}</code></template><template #status="{row}"><span class="badge" :class="row.revoked?'disabled':'active'">{{row.revoked?'已撤销':'有效'}}</span></template><template #last_used="{row}">{{date(row.last_used)}}</template><template #action="{row}"><button v-if="!row.revoked" class="text-btn danger-text" @click="detail=row;modal='revoke'">撤销</button></template></DataTable></div><section class="panel docs-panel"><div class="panel-heading"><h2>开发者文档</h2><a href="/docs" target="_blank" rel="noopener noreferrer" class="btn primary">查看完整 API 文档<ArrowUpRight :size="16"/></a></div><p>包含鉴权、余额、会员、报价、Session 检查、兑换、订单与撤回接口，以及字段、示例、错误状态和 OpenAPI 下载。</p><p class="muted">订单支持提链、付款报价、金额确认与结果核实。服务费以订单记录为准。</p></section></template>
<template v-else-if="route==='/invites'"><div class="page-heading"><div><span class="eyebrow">GROW TOGETHER</span><h1>伙伴计划</h1><p>把清晰有序的订阅体验，分享给更多伙伴。</p></div></div><section class="invite-banner"><Gift :size="48"/><div><h2>好用的工作台，值得分享。</h2><p>邀请关系现在即可记录。返利结算将在支付功能接入后开放。</p><div class="copy-field"><input readonly :value="inviteURL" aria-label="邀请链接"/><button class="btn primary" @click="action(()=>copy(inviteURL))"><Copy :size="16"/>复制邀请</button></div></div></section><div class="section-heading"><h2>通过你加入的伙伴</h2><span class="pill">{{items.length}} 位</span></div><div class="panel"><DataTable :rows="items" :columns="[{key:'email',label:'伙伴邮箱（脱敏）'},{key:'created_at',label:'加入时间'}]"><template #created_at="{row}">{{date(row.created_at)}}</template></DataTable></div></template>
<template v-else-if="route==='/renewal'"><div class="page-heading"><div><span class="eyebrow">SUBSCRIPTION SETTINGS</span><h1>续费管理</h1><p>单独关闭已有订阅的自动续费，或查看订阅办理中的续费设置。</p></div></div><RenewalPage/><h2 class="renewal-orders-title">订阅办理记录</h2><div class="panel"><DataTable :rows="items.filter(x=>x.workflow==='subscription')" :columns="[{key:'email',label:'订阅账号'},{key:'product_name',label:'方案'},{key:'renewal',label:'续费设置'},{key:'action',label:'详情'}]"><template #renewal="{row}">{{({kept:'保留自动续费',disabled:'已关闭自动续费',pending:'等待处理',review:'待核实',not_started:'尚未开始'} as Row)[row.renewal]||row.renewal}}</template><template #action="{row}"><button class="text-btn" @click="showOrder(row)">查看进度</button></template></DataTable></div></template>
<ProfilePage v-else-if="route==='/profile'" :user="user" @refresh="emit('refresh')" @logout="emit('logout')" @order="showOrder"/>
<div v-else class="empty"><h2>页面不存在</h2><a href="#/home">返回工作台</a></div>
<Modal v-if="modal" :title="({order:'订单详情',terms:'服务约定',topup:'提交充值申请',key:'创建访问密钥',revoke:'撤销访问密钥'} as Row)[modal]||'详情'" :wide="modal==='order'" @close="modal='';newKey=''">
<template v-if="modal==='order'"><div class="detail-title"><div><h3>{{detail.order?.product_name}}</h3><p>{{detail.order?.email}}</p><small class="mono">{{detail.order?.id}}</small></div><span class="badge order-status" :class="orderTone(detail.order)">{{orderLabel(detail.order)}}</span></div><ProgressTrack :status="detail.order?.status" :payment-state="detail.payment?.state" :workflow="detail.order?.workflow" :renewal="detail.order?.renewal" :activation="detail.order?.activation"/><CheckoutResult v-if="detail.order?.workflow!=='subscription'" :checkout="detail.checkout" :payment-state="detail.payment?.state"/><PaymentPanel v-if="detail.order?.workflow==='subscription'||detail.payment?.state" :order="detail.order" :payment="detail.payment" :checkout="detail.checkout" @refresh="showOrder(detail.order);emit('refresh')"/><p v-if="detailRefreshError" class="muted">{{detailRefreshError}}</p><div class="callout" v-if="detail.order?.status==='draft'">方案已保存。本订单尚未生成结账链接或发起付款。</div><div class="timeline"><div v-for="(e,i) in detail.events" :key="i"><span class="timeline-dot"></span><small>{{date(e.created_at)}}</small><p>{{e.message}}</p></div></div><button v-if="detail.order?.workflow!=='subscription'&&!detail.payment?.state&&['draft','queued','awaiting_payment'].includes(detail.order?.status)" class="btn secondary" :disabled="busy" @click="cancelOrder(detail.order.id)">撤回此方案</button></template>
<div v-else-if="modal==='terms'" class="pre-wrap">{{pub.site.terms}}</div>
<form v-else-if="modal==='topup'" @submit.prevent="submit(async()=>{await api('/topups','POST',{amount:Math.round(topupAmount*100),proof});notify('申请已提交，等待运营核实到账');modal='';proof='';await load()})"><div class="callout">此处只提交入账申请，不发起扣款。请先与运营确认收款方式并完成转账，勿在备注填写银行卡或密码。</div><label>申请金额（R）<input v-model.number="topupAmount" type="number" required min="1" step="0.01"/></label><label>转账凭据 / 备注<textarea v-model="proof" maxlength="500" placeholder="时间、渠道、交易编号等核对信息"></textarea></label><button class="btn primary full" :disabled="busy">提交审核</button></form>
<template v-else-if="modal==='key'"><form v-if="!newKey" @submit.prevent="submit(async()=>{const v=await api('/keys','POST',{name:keyName});newKey=v.key;keyName='';await load()})"><label>用途名称<input v-model="keyName" required maxlength="80" placeholder="例如：生产业务系统"/></label><button class="btn primary full" :disabled="busy">生成密钥</button></form><div v-else><div class="alert">请现在保存，下次无法再次显示完整密钥。</div><pre class="secret-display">{{newKey}}</pre><button class="btn primary" @click="action(()=>copy(newKey))"><Copy :size="16"/>复制密钥</button></div></template>
<template v-else-if="modal==='revoke'"><p>撤销「{{detail.name}}」后，使用它的请求将立即失效。</p><button class="btn danger" :disabled="busy" @click="submit(async()=>{await api('/keys/'+detail.id,'DELETE');modal='';await load();notify('密钥已撤销')})">确认撤销</button></template></Modal></div></template>

<style scoped>
.subscription-form{grid-template-columns:minmax(0,1.6fr) minmax(320px,1fr);align-items:start}.subscription-form .form-panel{padding:26px 28px}.subscription-form .panel-heading{margin-bottom:22px}.subscription-form .divider{margin:22px 0}.subscription-form .order-summary{padding:26px}.subscription-form .order-summary>ul{display:none}.subscription-form .summary-line{margin:13px 0}.subscription-form .summary-total{margin:20px 0;padding:20px 0}.subscription-form .callout{margin:16px 0;padding:14px}.payment-entry-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.payment-entry-heading span{font-size:11px;color:var(--muted)}.subscription-payment label{margin-bottom:10px}.subscription-payment textarea{font-family:Consolas,monospace;font-size:14px;letter-spacing:.2px;min-height:74px}.subscription-payment label small{font-size:11px;font-weight:400;line-height:1.7}.card-line-error{font-size:12px;color:#b64242;margin:8px 0 12px}.card-line-ready{display:flex;gap:8px;align-items:center;flex-wrap:wrap;background:#edf7f2;color:#27795b;padding:10px 12px;border-radius:8px;font-size:12px;margin:12px 0}.card-line-ready button{margin-left:auto}.renewal-choice{border-top:1px solid var(--line);margin-top:18px;padding-top:16px}.renewal-choice .checkbox-label{margin-bottom:6px}.renewal-choice p{font-size:11px;color:var(--muted)}
@media(max-width:1100px){.subscription-form{grid-template-columns:minmax(0,1fr)}.subscription-form .order-summary{position:static}}@media(max-width:760px){.subscription-form .form-panel,.subscription-form .order-summary{padding:20px}.payment-entry-heading{align-items:flex-start;flex-direction:column;gap:5px}}
</style>
